// src/App.jsx
import React, { useState } from "react";
import S from "./utils/storage";
import T from "./constants/translates";
import Sidebar from "./components/layout/Sidebar";
import Footer from "./components/Footer";
import { fetchAgriNews } from "./utils/api"; // ← imported from api.js

// Pages
import Dashboard        from "./pages/Dashboard";
import AgroBot          from "./pages/AgroBot";
import DiseaseDetection from "./pages/DiseaseDetection";
import FarmMap          from "./pages/FarmMap";
import MarketPrices     from "./pages/MarketPrices";
import Community        from "./pages/Community";
import Schemes          from "./pages/Schemes";
import Shops            from "./pages/Shops";
import Profile          from "./pages/Profile";
import AuthPage         from "./pages/AuthPage";

// ─────────────────────────────────────────────────────────────────────────────
// NotificationBell
// ─────────────────────────────────────────────────────────────────────────────

const AGRICULTURE_SOURCES = "Times Now, CNN-News18, NDTV 24x7, Republic TV";

function NotificationBell() {
  const [open,        setOpen]        = useState(false);
  const [read,        setRead]        = useState(false);
  const [news,        setNews]        = useState([]);
  const [loading,     setLoading]     = useState(false);
  const [error,       setError]       = useState("");       // ✅ FIX 1: was missing, caused crash
  const [lastFetched, setLastFetched] = useState(null);

  // ✅ FIX 2: renamed to loadNews — avoids conflict with imported fetchAgriNews
  // ✅ FIX 3: calls imported fetchAgriNews() from api.js, no inline fetch logic
  const loadNews = async () => {
    if (lastFetched && Date.now() - lastFetched < 10 * 60 * 1000) return;

    setLoading(true);
    setError("");

    try {
      const parsed = await fetchAgriNews();  // ← from utils/api.js
      setNews(parsed);
      setRead(false);
      setLastFetched(Date.now());
    } catch (err) {
      console.error("Agri news fetch failed:", err);
      setError(err.message || "Failed to load news");
      setNews([]);
    } finally {
      setLoading(false);
    }
  };

  // Fetch on first open
  const handleOpen = () => {
    const next = !open;
    setOpen(next);
    if (next && news.length === 0) loadNews();  // ✅ calls loadNews
  };

  const severityColor = (s) =>
    s === "high" ? "#e53e3e" : s === "medium" ? "#d97706" : "#2e9b4e";

  const severityBg = (s) =>
    s === "high" ? "#fff5f5" : s === "medium" ? "#fffbeb" : "#f0fff4";

  return (
    <div style={{ position: "relative", display: "inline-block" }}>

      {/* Bell Button */}
      <button
        onClick={handleOpen}
        style={{
          width: 38, height: 38, borderRadius: "50%",
          background: "#fff", border: "1px solid #e0eae0",
          cursor: "pointer", display: "flex", alignItems: "center",
          justifyContent: "center",
          boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
          transition: "transform 0.15s",
          position: "relative",
        }}
      >
        <span style={{ fontSize: 17 }}>🔔</span>
        {!read && news.length > 0 && (
          <span style={{
            position: "absolute", top: 4, right: 4,
            width: 15, height: 15, borderRadius: "50%",
            background: "#e53e3e", border: "2px solid #fff",
            fontSize: 8, fontWeight: 700, color: "#fff",
            display: "flex", alignItems: "center", justifyContent: "center",
          }}>
            {news.length}
          </span>
        )}
      </button>

      {/* Dropdown */}
      {open && (
        <>
          {/* Backdrop */}
          <div
            onClick={() => setOpen(false)}
            style={{ position: "fixed", inset: 0, zIndex: 998 }}
          />

          <div style={{
            position: "absolute", top: 46, right: 0,
            width: 330, background: "#fff", borderRadius: 14,
            boxShadow: "0 8px 32px rgba(0,0,0,0.15)",
            zIndex: 999, overflow: "hidden",
            fontFamily: "Inter, sans-serif",
          }}>

            {/* Header */}
            <div style={{
              padding: "12px 14px",
              background: "linear-gradient(135deg, #062010, #0e3a1c)",
              display: "flex", justifyContent: "space-between", alignItems: "center",
            }}>
              <div>
                <div style={{ fontSize: 13, fontWeight: 600, color: "#fff" }}>
                  🌾 Agriculture News
                </div>
                <div style={{ fontSize: 10, color: "rgba(255,255,255,0.5)", marginTop: 2 }}>
                  {AGRICULTURE_SOURCES}
                </div>
              </div>
              <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                {/* ✅ FIX 4: clears cache before calling loadNews so refresh always works */}
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    setLastFetched(null);
                    loadNews();
                  }}
                  style={{
                    background: "rgba(255,255,255,0.12)", border: "none",
                    borderRadius: 6, padding: "4px 8px", cursor: "pointer",
                    fontSize: 11, color: "#fff",
                  }}
                >
                  {loading ? "⏳" : "🔄"}
                </button>
                {!read && news.length > 0 && (
                  <span
                    onClick={() => setRead(true)}
                    style={{ fontSize: 10, color: "rgba(255,255,255,0.6)", cursor: "pointer" }}
                  >
                    Mark read
                  </span>
                )}
              </div>
            </div>

            {/* Body */}
            <div style={{ maxHeight: 380, overflowY: "auto" }}>

              {/* Loading */}
              {loading && (
                <div style={{ padding: "28px 14px", textAlign: "center" }}>
                  <div style={{ fontSize: 24, marginBottom: 8 }}>🌿</div>
                  <div style={{ fontSize: 12, color: "#888" }}>Fetching live agriculture news…</div>
                  <div style={{ fontSize: 11, color: "#bbb", marginTop: 4 }}>
                    Searching {AGRICULTURE_SOURCES}
                  </div>
                </div>
              )}

              {/* ✅ FIX 5: Error state now shows the real error message */}
              {!loading && error && (
                <div style={{ padding: "16px 14px" }}>
                  <div style={{ fontSize: 12, color: "#e53e3e", marginBottom: 8, fontWeight: 600 }}>
                    ❌ Failed to load news
                  </div>
                  <div style={{
                    fontSize: 11, color: "#888", background: "#fff5f5",
                    padding: "8px 10px", borderRadius: 6,
                    wordBreak: "break-word", lineHeight: 1.5,
                  }}>
                    {error}
                  </div>
                  <button
                    onClick={(e) => { e.stopPropagation(); setLastFetched(null); loadNews(); }}
                    style={{
                      marginTop: 10, width: "100%", padding: "7px",
                      background: "#062010", color: "#fff", border: "none",
                      borderRadius: 7, cursor: "pointer", fontSize: 12,
                    }}
                  >
                    🔄 Retry
                  </button>
                </div>
              )}

              {/* Empty */}
              {!loading && !error && news.length === 0 && (
                <div style={{
                  padding: "24px 14px", textAlign: "center",
                  fontSize: 12, color: "#999",
                }}>
                  No news loaded yet. Click 🔄 to fetch.
                </div>
              )}

              {/* News items */}
              {!loading && !error && news.length > 0 && news.map((item, i) => (
                <div
                  key={i}
                  onClick={() => item.url && window.open(item.url, "_blank")}
                  style={{
                    padding: "10px 14px",
                    borderBottom: "1px solid #f0f5f0",
                    background: severityBg(item.severity),
                    cursor: item.url ? "pointer" : "default",
                    transition: "filter 0.1s",
                  }}
                  onMouseEnter={e => e.currentTarget.style.filter = "brightness(0.97)"}
                  onMouseLeave={e => e.currentTarget.style.filter = "none"}
                >
                  <div style={{ display: "flex", gap: 9, alignItems: "flex-start" }}>
                    <div style={{
                      width: 8, height: 8, borderRadius: "50%", flexShrink: 0,
                      background: read ? "#ccc" : severityColor(item.severity),
                      marginTop: 4,
                    }} />
                    <div style={{ flex: 1 }}>
                      <p style={{
                        fontSize: 12, color: "#1a2e1a",
                        lineHeight: 1.45, margin: "0 0 4px",
                      }}>
                        {item.title}
                      </p>

                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* Footer */}
            {!loading && news.length > 0 && (
              <div style={{
                padding: "8px 14px", fontSize: 10, color: "#bbb",
                textAlign: "center", borderTop: "1px solid #f0f0f0",
              }}>
                {lastFetched && `Updated ${new Date(lastFetched).toLocaleTimeString()} · `}
                Refreshes every 10 min
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// App
// ─────────────────────────────────────────────────────────────────────────────

export default function App() {
  const [user, setUser] = useState(() => S.get("current_user") || null);
  const [lang, setLang] = useState("en");
  const [page, setPage] = useState("dashboard");

  const t = (path) => {
    try {
      return path.split(".").reduce((obj, key) => obj[key], T[lang]) || path;
    } catch (e) {
      return path;
    }
  };

  const handleLogout = () => {
    S.del("current_user");
    setUser(null);
  };

  if (!user) return <AuthPage onLogin={(u) => setUser(u)} />;

  const pages = {
    dashboard: <Dashboard        user={user} setPage={setPage} t={t} />,
    bot:       <AgroBot          user={user} setPage={setPage} t={t} />,
    disease:   <DiseaseDetection user={user} setPage={setPage} t={t} />,
    map:       <FarmMap          user={user} setPage={setPage} t={t} />,
    market:    <MarketPrices     user={user} setPage={setPage} t={t} />,
    community: <Community        user={user} setPage={setPage} t={t} />,
    schemes:   <Schemes          user={user} setPage={setPage} t={t} />,
    shops:     <Shops            user={user} setPage={setPage} t={t} />,
    profile:   <Profile          user={user} t={t} setPage={setPage} onLogout={handleLogout} />,
  };

  return (
    <div style={{
      display: "flex", height: "100vh", width: "100vw",
      overflow: "hidden", background: "#f8fafc",
    }}>

      {/* 1. LEFT SIDEBAR */}
      <Sidebar user={user} page={page} setPage={setPage} />

      {/* 2. RIGHT CONTENT AREA */}
      <div style={{
        flex: 1, display: "flex", flexDirection: "column",
        height: "100%", overflowY: "auto",
      }}>

        {/* Top bar — bell anchored here so dropdown z-index is never blocked */}
        <div style={{
          display: "flex",
          justifyContent: "flex-end",
          alignItems: "center",
          padding: "12px 28px 0",
          position: "relative",
        }}>
          <NotificationBell />
        </div>

        {/* Page content */}
        <main style={{ flex: 1, padding: "16px 32px 32px" }}>
          {pages[page]}
        </main>

        {/* 3. FOOTER */}
        <Footer t={t} />
      </div>
    </div>
  );
}
